/*债券存续期 流程中*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T1.FINPROD_ID = T5.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE WHERE T4.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF03} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ AND T1.P_TOTLE_TRADE_ID IS NULL
AND T1.TOTLE_TRADE_ID = #{busiCode}
AND (EXISTS( select 1 from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and DEAL.PORTFOLIO_ID ) or T1.PS='T39') ORDER BY T1.MDATE DESC) UNION ALL /*质押式回购存续期 流程中*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, NULL finprodMarketId, NULL finprodAbbr, to_char(T4.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T4.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt,/*实收本息总额*/ null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType/*交易方向*/, T1.workflow_id workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL ptpd on ptpd.TRADE_ID = T4.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE WHERE T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF02}, #{FINPROD_TYPE_TGF03}) and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ and T1.PORTFOLIO_ID
ORDER BY T1.TRADE_DATE DESC) union all /*存款*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT TC4 ON T1.CHL_ID = TC4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE WHERE T4.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF07} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} and T1.TRADE_STATUS = #{TRADE_STATUS01} AND T1.P_TOTLE_TRADE_ID is null AND (T1.PORTFOLIO_ID IS NULL or T1.PS = #{PS_T38} or T1.PS = #{PS_C7}) AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ AND T1.P_TOTLE_TRADE_ID IS NULL AND EXISTS( select 1 from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where (DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID or deal.TOTLE_TRADE_ID = t1.TOTLE_TRADE_ID) and (DEAL.PORTFOLIO_ID OR T1.PORTFOLIO_ID )
and (DEAL.PORTFOLIO_ID IN
#{item}
OR T1.PORTFOLIO_ID IN
#{item} )
)
ORDER BY T1.MDATE DESC) union all /*拆借*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, null secAcctId, null secAcctName, null finprodMarketId, null finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt/*实付本息和*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T9 ON T1.FINPROD_ID = T9.FINPROD_ID and t1.BRANCH = T9.BRANCH LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE WHERE T1.BUSI_TYPE = #{COMMON_BUSINESS_TYPETRD11} and T1.TRADE_STATUS = #{TRADE_STATUS01}
ORDER BY T1.TRADE_DATE DESC) union all /*基金流程中*/ SELECT * FROM ( SELECT #{PAGE_DATE_STATUS03} statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, null portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, null vDate/*计息开始日*/, null mDate/*计息结束日*/, T1.INT_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 left join WFL_PA_TRD_FIN_DEAL_TOTAL T3 on T3.TOTLE_TRADE_ID =T1.TOTLE_TRADE_ID left join FIN_PRODUCT T4 on T4.FINPROD_ID =T1.FINPROD_ID inner join FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID =T1.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID =T1.CHL_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID where T1.PS IN (#{PS_T12},#{PS_T13},#{PS_T11}) and T5.TYPE_6 IN (#{FUND_ASSET_TYPE_F01},#{FUND_ASSET_TYPE_F02}) and T1.TRADE_STATUS = #{TRADE_STATUS01} and T1.IS_CANCEL = #{YESNO_N} ) union all /*计划类(净值型货币型)流程中*/ SELECT * FROM ( SELECT #{PAGE_DATE_STATUS03} statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, null portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, null vDate/*计息开始日*/, null mDate/*计息结束日*/, T1.INT_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 left join WFL_PA_TRD_FIN_DEAL_TOTAL T3 on T3.TOTLE_TRADE_ID =T1.TOTLE_TRADE_ID left join FIN_PRODUCT T4 on T4.FINPROD_ID =T1.FINPROD_ID inner join FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID =T1.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID =T1.CHL_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID where T1.PS IN (#{PS_T12},#{PS_T13},#{PS_T11}) and T4.PROFIT_TYPE IN (#{PROFIT_TYPE_JZ}, #{PROFIT_TYPE_HB}) and T4.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F17} and T1.TRADE_STATUS = #{TRADE_STATUS01} and T1.IS_CANCEL = #{YESNO_N} ) union all /*计划类(利率型)流程中*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, T3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, null portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T4.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT PF ON T1.CHL_ID = PF.FINPROD_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ AND T1.PORTFOLIO_ID IS NULL AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND T1.IS_CANCEL = #{YESNO_N} AND T1.BUSI_TYPE = #{TRD15} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17} AND T4.PROFIT_TYPE = #{PROFIT_TYPE02} AND EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND DEAL.PORTFOLIO_ID )
ORDER BY T1.TRADE_DATE DESC ) union all /*买断式回购*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID WHERE T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF02}, #{FINPROD_TYPE_TGF03}) and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ and T1.PORTFOLIO_ID
ORDER BY T1.TRADE_DATE DESC) union all /*项目类*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ AND T1.IS_CANCEL = #{YESNO_N} AND T1.BUSI_TYPE = #{TRD15} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17} AND T1.PORTFOLIO_ID IS NULL AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND DEAL.PORTFOLIO_ID )
ORDER BY T1.TRADE_DATE DESC ) union all /*债券借贷*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID WHERE T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF29}, #{FINPROD_TYPE_TGF30}) and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ and T1.PORTFOLIO_ID
ORDER BY T1.TRADE_DATE DESC) union all /*股票*/ select * from ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T6.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T6.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T6.FPRICE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T6.SHARE_AMT shareAmt, T6.CCY ccy, to_char(T6.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN (select SUM(T6.FPRICE_AMT) FPRICE_AMT,T6.VDATE,T6.MDATE SUM(T6.SHARE_AMT) SHARE_AMT,T6.CCY,T6.PS,T6.TOTLE_TRADE_ID,T6.SETTLE_DATE from WFL_TRD_PRODUCT_DEAL T6 group by T6.TOTLE_TRADE_ID,T6.CCY,T6.PS, T6.SETTLE_DATE,T6.VDATE,T6.MDATE ) T6 ON T1.TOTLE_TRADE_ID = T6.TOTLE_TRADE_ID AND T6.PS = #{PS_T13,jdbcType=VARCHAR} left join PTL_PORTFOLIO T2 on T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID AND FP.IS_CHL = #{YES_OR_NO_Y,jdbcType=VARCHAR} LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID WHERE T1.P_TRADE_ID IS NULL AND T1.FINPROD_TYPE2 = #{F10} and nvl(T2.PARENT_PORTFOLIO_ID,'null') = 'null' ) union all /*利率互换*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T21.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T21.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T21.FPRICE_AMT tradeAmt/*实收本息总额*/, T31.FPRICE_AMT tradeAmt2/*实收本息总额*/, T1.SHARE_AMT shareAmt, T21.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT T41 ON T1.FINPROD_ID = T41.FINPROD_ID AND T1.BRANCH = T41.BRANCH LEFT JOIN WFL_TRD_PRODUCT_DEAL T21 ON T1.TOTLE_TRADE_ID = T21.TOTLE_TRADE_ID AND ((T21.PS = #{psR} and T41.IRS_TYPE = #{irsType01}) OR (T21.PS = #{psP} and T41.IRS_TYPE = #{irsType02})) LEFT JOIN WFL_TRD_PRODUCT_DEAL T31 ON T1.TOTLE_TRADE_ID = T31.TOTLE_TRADE_ID AND ((T31.PS = #{psR} and T41.IRS_TYPE = #{irsType02}) OR (T31.PS = #{psP} and T41.IRS_TYPE = #{irsType01})) LEFT JOIN PTL_TRADE PT ON NVL(NVL(T21.P_TRADE_ID, T21.TRADE_ID), NVL(T31.P_TRADE_ID, T31.TRADE_ID)) = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO T2 ON PT.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND T1.IS_CANCEL = #{YESNO_N} AND T41.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF14} AND T2.INVEST_YESORNO='Y' AND T1.P_TRADE_ID IS NULL/*撤销的数据不展示*/ AND T1.P_TOTLE_TRADE_ID IS NULL
AND T1.PORTFOLIO_ID ORDER BY T1.MDATE DESC) union all /*期权*/ SELECT * FROM( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, null secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(FTP.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(FTP.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TFDT ON T1.FINPROD_ID = TFDT.TOTLE_TRADE_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON T1.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T1.FINPROD_ID = T5.FINPROD_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID WHERE T1.PS IN ('T59','T60','T61') AND T1.FINPROD_TYPE2 = 'F35' AND T1.TRADE_STATUS = '01' ) union all /*融入*/ select * from ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, T1.WORKFLOW_ID workflowId FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID WHERE T1.FINPROD_TYPE2 = 'F01' AND T1.TG_BUSI_TYPE IN ('137', '138') AND wtdta.MP_FINPROD_ID IS NOT NULL AND T1.PORTFOLIO_ID
ORDER BY T1.MDATE)

/*债券存续期 有效数据*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, NULL workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T1.FINPROD_ID = T5.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.IS_CANCEL = #{YESNO_N} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01}
AND T1.TOTLE_TRADE_ID = #{busiCode}
AND T1.P_TOTLE_TRADE_ID IS NULL
AND (EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL
LEFT JOIN TRD_PRODUCT_DEAL tpd ON tpd.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID
WHERE (DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID OR (DEAL.PS IN (#{PS_T07},#{PS_T08},#{PS_T09},#{PST22},#{PST23},#{PST24}) AND DEAL.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND tpd.TRADE_MARKET = #{TRADE_PLACE_01}))
and (DEAL.PORTFOLIO_ID OR tpda.PORTFOLIO_ID ) ) or T1.PS='T39') ORDER BY T1.MDATE DESC) union all /*质押式回购存续期*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, NULL finprodMarketId, NULL finprodAbbr, to_char(T4.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T4.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt,/*实收本息总额*/ null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType/*交易方向*/, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO T2 ON PT.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN TRD_PRODUCT_DEAL ptpd on ptpd.TRADE_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID WHERE T2.INVEST_YESORNO = 'Y' AND T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF02}, #{FINPROD_TYPE_TGF03}) and T1.PORTFOLIO_ID and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} and t1.PS in (#{PST07},#{PST56},#{PS_TQZZ},#{PS_YQFS})
ORDER BY T1.TRADE_DATE DESC) union all SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, t3.PA_BUSS_TYPE paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.CHL_ID secAcctId, fp.FINPROD_NAME secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND T1.IS_CANCEL = #{YESNO_N} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF07} AND T1.P_TOTLE_TRADE_ID is null AND EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where (DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID or deal.TOTLE_TRADE_ID = t1.TOTLE_TRADE_ID) and (DEAL.PORTFOLIO_ID OR T1.PORTFOLIO_ID )
and (DEAL.PORTFOLIO_ID IN
#{item}
OR T1.PORTFOLIO_ID IN
#{item} )
